.woocommerce ul.products li.product.featured {
	position: relative;
}
.woocommerce ul.products li.product.featured::before {
	content: "Προτεινόμενο";
	position: absolute;
	top: .5em;
	right: .5em;
	z-index: 9;
	padding: .2em .6em;
	border-radius: 3px;
	background: #dba617;
	color: #fff;
	font-size: .75em;
	font-weight: 600;
	line-height: 1.6;
}
